SELECT CASE WHEN COUNT(pk_pers_id_persona) > 0 THEN 1 ELSE 0 END AS result
FROM persona
WHERE pk_pers_id_persona = #{id}

SELECT CASE WHEN COUNT(pk_fipa_id_ficha_parvulo) > 0 THEN 1 ELSE 0 END AS result
FROM ficha_parvulo
WHERE pk_fipa_id_ficha_parvulo = #{id}

SELECT CASE WHEN COUNT(pk_trgf_id_tipo_relacion_grupo_familiar) > 0 THEN 1 ELSE 0 END AS result
FROM tipo_relacion_grupo_familiar
WHERE pk_trgf_id_tipo_relacion_grupo_familiar = #{id}
